  const raw = async (path, key, init = {}) => { const r = await fetch(base + path, { redirect: 'manual', ...init, headers: { ...(key ? { authorization: `Bearer ${key}` } : {}), ...(init.headers || {}) } }); let data = null; const text = await r.text(); try { data = JSON.parse(text); } catch { data = text; } return { status: r.status, headers: r.headers, data }; };
