  const stu = await raw(`${OR}/students`, KEY1); log(stu.status === 200 && stu.data.users.length === 7 && stu.data.users.every((u) => u.role === 'student' && u.givenName && u.familyName !== undefined), 'all seven children are listed as students');
  log(stu.data.users.every((u) => !u.email && !u.phone && !('sms' in u)), 'no email address or phone number is shared without that scope');
  const pg = await raw(`${OR}/students?limit=3&offset=2`, KEY1); log(pg.data.users.length === 3 && pg.headers.get('x-total-count') === '7' && /rel="next"/.test(pg.headers.get('link') || '') && /rel="prev"/.test(pg.headers.get('link') || ''), 'paging works and says where the next and previous pages are');
  const one = await raw(`${OR}/students/${stu.data.users[0].sourcedId}`, KEY1); log(one.status === 200 && one.data.user.sourcedId === stu.data.users[0].sourcedId, 'one child can be read');
  const flt = await raw(`${OR}/users?filter=${encodeURIComponent("role='teacher'")}`, KEY1); log(flt.status === 200 && flt.data.users.length === 1 && flt.data.users[0].role === 'teacher', 'a filter narrows the list');
  const srt = await raw(`${OR}/students?sort=givenName&orderBy=desc&fields=sourcedId,givenName`, KEY1); log(srt.status === 200 && Object.keys(srt.data.users[0]).sort().join() === 'givenName,sourcedId', 'sorting and choosing fields work');
  const badf = await raw(`${OR}/students?filter=${encodeURIComponent("nonsense~~")}`, KEY1); log(badf.status === 400 && badf.data.imsx_codeMajor === 'failure', 'a filter that makes no sense is refused in the standard format');
  const badl = await raw(`${OR}/students?limit=-3`, KEY1); log(badl.status === 400 || (badl.status === 200 && badl.data.users.length > 0), 'a bad limit is refused or corrected, never an error page');
