  const oa = await raw(`${OPEN}/attendance/daily?date=${today}`, KEY2); log(oa.status === 200 && oa.data.total === 2 && oa.data.records.some((r) => r.status === 'Absent' && r.studentId === String(X.k7[0]._id)), 'attendance for a day is read through the open door');
  await expect('a missing date is refused', Promise.resolve(await raw(`${OPEN}/attendance/daily`, KEY2)), [422]); await expect('an impossible date is refused', Promise.resolve(await raw(`${OPEN}/attendance/daily?date=2026-02-30`, KEY2)), [422]);
  log((await DisclosureLog.countDocuments({ schoolId: X.s._id, connectorId: C2, channel: 'open_api' })) >= 1, 'that read is in the disclosure log');
  await expect('a connection that was approved cannot be edited while it is on', PU(`${I}/connectors/${C2}`, { name: 'Renamed' }, X.W1), [409]);
  await expect('it can be paused with a reason', PO(`${I}/connectors/${C2}/pause`, { reason: 'Checking the scope' }, X.W1)); log((await raw(`${OR}/orgs`, KEY2)).status === 401, 'a paused key stops working at once');
  const widen = await PU(`${I}/connectors/${C2}`, { scopes: ['roster.read', 'roster.contact', 'attendance.read', 'roster.guardians', 'fees.read'] }, X.W1); log(widen.status === 200 && widen.data.connector.review.status === 'none' && widen.data.connector.review.why.length === 4, 'widening a paused key asks for a new review');
  await expect('so resuming it is refused until it is reviewed again', PO(`${I}/connectors/${C2}/resume`, {}, X.W1), [409]);
  await PU(`${I}/connectors/${C2}`, { scopes: ['roster.read'] }, X.W1); const back = await PO(`${I}/connectors/${C2}/resume`, {}, X.W1); log(back.status === 200 || back.status === 409, 'narrowing it again can be resumed or reviewed, never silently widened');

  // ── 6. the same rule in a school with one administrator ──
  const y1 = await make(Y.W1, { kind: 'api_key', name: 'Only admin key', purpose: 'A sensitive key in a one-administrator school', scopes: ['attendance.read'] }); const ya = await PO(`${I}/connectors/${y1.data.connector.id}/activate`, {}, Y.W1); const yd = await PO(`${I}/connectors/${y1.data.connector.id}/decide`, { approve: true, note: 'I am the only administrator' }, Y.W1);
